/**
 * Strict source grammar for a new owner-approved Node contract test.
 * This pure renderer is shared by the synthesizer and repair critic: model
 * suggestions cannot launder arbitrary JS by prepending a magic comment.
 */
export const CONTRACT_PREFIX=
 '// Generated by Continuum contract operator; owner-specified expected outputs.\n';
const FILE=/^\.github\/continuum\/([A-Za-z][A-Za-z0-9_-]{0,63})\.contract\.test\.mjs$/;
const NAME=/^[A-Za-z_][A-Za-z0-9_]{0,63}$/;
const PRIMITIVE=v=>v===null||typeof v==='boolean'||
 (typeof v==='number'&&Number.isFinite(v))||
 (typeof v==='string'&&v.length<=120);

export function renderOwnerNodeContract(file,exportName,casesJson){
 const path=FILE.exec(file??'');
 if(!path||!NAME.test(exportName??'')||typeof casesJson!=='string'||
    casesJson.length>300)return null;
 let cases;
 try{
  cases=JSON.parse(casesJson);
  if(!Array.isArray(cases)||cases.length<1||cases.length>4)return null;
  for(const c of cases)if(!c||typeof c!=='object'||
   !Array.isArray(c.args)||c.args.length>3||
   !c.args.every(PRIMITIVE)||!Object.hasOwn(c,'expected')||
   !PRIMITIVE(c.expected))return null;
 }catch{return null;}
 const lines=[
  CONTRACT_PREFIX.trimEnd(),
  "import test from 'node:test';",
  "import assert from 'node:assert/strict';",
  'import { '+exportName+' } from '+JSON.stringify('./'+path[1]+'.mjs')+';',
  ''
 ];
 for(const [i,c] of cases.entries()){
  lines.push('test('+JSON.stringify('owner contract '+exportName+' #'+(i+1))+',()=>{');
  lines.push('  assert.deepStrictEqual('+exportName+'('+
    c.args.map(v=>JSON.stringify(v)).join(',')+'),'+JSON.stringify(c.expected)+');');
  lines.push('});');
 }
 lines.push('');
 const source=lines.join('\n');
 if(source.length>3500)return null;
 return source;
}
